def check_sequence(g1, g2, g3, length=2025):
    seq = [g1, g2, g3]
    for i in range(3, length):
        # g(n) + g(n+1) = g(n+2)g(n+3) - 840
        # n = i-2: g(i-2) + g(i-1) = g(i) * g(i+1) - 840
        # g(i+1) = (g(i-2) + g(i-1) + 840) / g(i)
        # Wait, let's use the index i properly.
        # seq[0], seq[1], seq[2] are given.
        # n=1: seq[0] + seq[1] = seq[2] * seq[3] - 840
        # seq[3] = (seq[0] + seq[1] + 840) / seq[2]
        # n=2: seq[1] + seq[2] = seq[3] * seq[4] - 840
        # seq[4] = (seq[1] + seq[2] + 840) / seq[3]
        # Generally: seq[i] = (seq[i-3] + seq[i-2] + 840) / seq[i-1]
        num = seq[i-3] + seq[i-2] + 840
        if num % seq[i-1] != 0:
            return None
        val = num // seq[i-1]
        if val < 2:
            return None
        seq.append(val)
    return sum(seq)

results = set()
for g1 in range(2, 101):
    for g2 in range(2, 101):
        for g3 in range(2, 101):
            s = check_sequence(g1, g2, g3)
            if s is not None:
                results.add(s)

print(results)

def check_seq(g1, g2, g3):
    seq = [g1, g2, g3]
    for i in range(3, 50):
        num = seq[i-3] + seq[i-2] + 840
        if num % seq[i-1] != 0: return None
        val = num // seq[i-1]
        if val < 2: return None
        seq.append(val)
    return seq

results = set()
for g1 in range(2, 100):
    for g2 in range(2, 100):
        for g3 in range(2, 100):
            s = check_seq(g1, g2, g3)
            if s:
                # Check if it became periodic
                # If it's periodic with period p, then s[-p:] == s[-2p:-p]
                for p in range(1, 10):
                    if s[-p:] == s[-2*p:-p]:
                        # Calculate the sum for 2025 terms
                        # Use the sequence to find g(n)
                        # The sequence might have a pre-period
                        # But for the sake of the sum, we can just extend it.
                        full_seq = [g1, g2, g3]
                        for j in range(3, 2025):
                            full_seq.append((full_seq[j-3] + full_seq[j-2] + 840) // full_seq[j-1])
                        results.add(sum(full_seq))
                        break
print(results)
